    return {
      t: 0,
      pos: { x: -2.1 + parameters.offset.x, y: BODY_HEIGHT, z: -1.65 + parameters.offset.z },
      vel: { x: 0, y: 0, z: 0 },
      att: { roll: 0, pitch: 0, yaw: 0 },
      rates: { roll: 0, pitch: 0, yaw: 0 },
      motors: [0, 0, 0, 0],
      integral: { roll: 0, pitch: 0 },
      gateIndex: 0,
      landedFor: 0,
      airborne: false,
      reason: null,
